    private void maybeLoadCataloguePage(){
        if(!(route.equals("Movies")||route.equals("TV Shows"))||catalogueLoading||!catalogueHasMore||grid==null||!(grid.getAdapter() instanceof Posters)||SystemClock.elapsedRealtime()<catalogueRetryAfter)return;
        Posters adapter=(Posters)grid.getAdapter();int last=-1;RecyclerView.LayoutManager manager=grid.getLayoutManager();
        if(manager instanceof GridLayoutManager)last=((GridLayoutManager)manager).findLastVisibleItemPosition();
        else if(manager instanceof StaggeredGridLayoutManager)for(int n:((StaggeredGridLayoutManager)manager).findLastVisibleItemPositions(null))last=Math.max(last,n);
        if(last<0||last<adapter.getItemCount()-Math.max(4,adapter.columns*2))return;
        final int request=generation,next=page+1,type=route.equals("Movies")?1:2;final JSONObject requestedFilters;
        try{requestedFilters=new JSONObject(filters.toString());}catch(JSONException error){return;}
        catalogueLoading=true;status.setText("Loading more\u2026");
        try{network.execute(()->{try{List<JSONObject> batch=api.catalogue(type,next,requestedFilters);ui.post(()->{
            if(request!=generation||isDestroyed())return;catalogueLoading=false;Set<String> seen=new HashSet<>();for(JSONObject item:adapter.items)seen.add(item.optString("subjectId"));int before=adapter.items.size();
            for(JSONObject item:batch)if(seen.add(item.optString("subjectId")))adapter.items.add(item);int added=adapter.items.size()-before;page=next;catalogueHasMore=added>0;
            if(added>0)adapter.notifyItemRangeInserted(before,added);status.setText("");if(added>0)grid.post(this::maybeLoadCataloguePage);
        });}catch(Exception error){ui.post(()->{if(request!=generation||isDestroyed())return;catalogueLoading=false;catalogueRetryAfter=SystemClock.elapsedRealtime()+5000;status.setText("Couldn't load more. Scroll again to retry.");});}});}catch(RejectedExecutionException busy){catalogueLoading=false;catalogueRetryAfter=SystemClock.elapsedRealtime()+3000;status.setText("Scroll again to load more titles.");}
    }
