    private JSONArray verifiedBanners;
    private JSONArray verifiedBanners(){if(verifiedBanners==null){try{verifiedBanners=new JSONArray(Utf8Json.decode(Api.read(getAssets().open("verified-banners.json"),128000)));}catch(Exception ignored){verifiedBanners=new JSONArray();}}return verifiedBanners;}
    private String bannerUrl(JSONObject item){
        try{JSONArray verified=verifiedBanners();for(int i=0;i<verified.length();i++){JSONObject record=verified.getJSONObject(i);JSONArray ids=record.getJSONArray("subjectIds"),titles=record.getJSONArray("titles");boolean sameId=false,sameTitle=false;for(int j=0;j<ids.length();j++)if(ids.getString(j).equals(item.optString("subjectId")))sameId=true;for(int j=0;j<titles.length();j++)if(titles.getString(j).equals(item.optString("title")))sameTitle=true;if(sameId&&sameTitle&&item.optString("releaseDate").startsWith(record.getString("year"))&&item.optInt("subjectType")==record.getInt("subjectType"))return record.getString("url");}}catch(Exception ignored){}
        for(String key:new String[]{"stills","banner","backdrop"}){Object value=item.opt(key);JSONArray candidates=value instanceof JSONArray?(JSONArray)value:new JSONArray().put(value);for(int i=0;i<candidates.length();i++){JSONObject candidate=candidates.optJSONObject(i);if(candidate==null)continue;double width=candidate.optDouble("width"),height=candidate.optDouble("height");if(width>=640&&height>=320&&Double.isFinite(width)&&Double.isFinite(height)&&width/height>=1.45&&width/height<=3.2&&(!candidate.has("subjectId")||candidate.optString("subjectId").equals(item.optString("subjectId"))))return candidate.optString("url");}}return "";
    }

