    private void loadImage(ImageView view,String url,int requestedWidth){
        if(artworkLoader==null)artworkLoader=new ArtworkLoader(ui,bitmapCache,this::fetchArtwork,new ArtworkFallback(panel,secondary),(ThreadPoolExecutor)images);
        final java.lang.ref.WeakReference<ImageView> target=new java.lang.ref.WeakReference<>(view);
        artworkLoader.load(view,url,requestedWidth,()->{ImageView image=target.get();if(image!=null&&heroHeader!=null&&image==heroHeader.art)heroHeader.watermark.setVisibility(View.GONE);});
    }
    private Bitmap fetchArtwork(String url,int width)throws Exception{
        String resized=Api.artwork(url,width);byte[] cached=uiCache==null?null:uiCache.readArtwork(resized);
        if(cached!=null){Bitmap image=decodeArtwork(cached,width);if(image!=null)return image;uiCache.removeArtwork(resized);}
        byte[] bytes=api.artworkBytes(resized,UiCache.MAX_ARTWORK_BYTES);Bitmap image=decodeArtwork(bytes,width);
        if(image==null)throw new IOException("Artwork unavailable");
        if(uiCache!=null)uiCache.writeArtwork(resized,bytes);return image;
    }
    private Bitmap decodeArtwork(byte[] bytes,int width){
        if(bytes==null||bytes.length==0)return null;BitmapFactory.Options size=new BitmapFactory.Options();size.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,size);
        if(size.outWidth<=0||size.outHeight<=0||size.outWidth>16384||size.outHeight>16384)return null;
        int sample=1;while(size.outWidth/sample>Math.max(640,width)||size.outHeight/sample>1440)sample*=2;
        BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;options.inPreferredConfig=Bitmap.Config.RGB_565;return BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);
    }

