    private void runSearch(String value){final String keyword=RecentSearches.clean(value);if(keyword.isEmpty()){clearSearchResults();return;}saveBrowseState();if(searchInput!=null&&searchInput.isAttachedToWindow()&&!keyword.equals(searchInput.getText().toString())){searchInput.setText(keyword);searchInput.setSelection(keyword.length());}query=keyword;rememberSearch(keyword);activeBrowseKey=null;grid=null;generation++;((ThreadPoolExecutor)network).getQueue().clear();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);status.setText("Searching…");work(()->api.search(keyword),items->{List<JSONObject> safe=allowedTitles(items);showTitles(safe,false);status.setText(safe.size()+" search results");},error->{status.setText("Search failed. Try again.");content.removeAllViews();TextView note=text("Couldn't load results. Check your connection and retry.",15);note.setTextColor(secondary);note.setPadding(dp(16),dp(20),dp(16),dp(12));content.addView(note);Button retry=button("Retry","Retry search",()->{if(route.equals("Search")&&subject==null&&query.equals(keyword))runSearch(keyword);});LinearLayout.LayoutParams retryLp=new LinearLayout.LayoutParams(-2,dp(48));retryLp.leftMargin=dp(16);content.addView(retry,retryLp);});}
