    private boolean adultAllowed(){return library.settings().optBoolean("allowAdultContent",false);}
    private boolean contentBlocked(JSONObject item){return !adultAllowed()&&AdultContentPolicy.markedAdult(item);}
    private List<JSONObject> allowedTitles(List<JSONObject> values){List<JSONObject> safe=new ArrayList<>();for(JSONObject item:values)if(!contentBlocked(item))safe.add(item);return safe;}
    private void openDetail(JSONObject item){openDetail(item,true);}
    private void openDetail(JSONObject item,boolean autoPlay){
        if(contentBlocked(item)){toast("18+ content is disabled in Settings.");return;}
        saveBrowseState();setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);releasePlayer();generation++;
        if(subject==null||!subject.optString("subjectId").equals(item.optString("subjectId"))){season=0;episode=0;resumeSelectionPending=true;watchSeason=-1;}
        ((ThreadPoolExecutor)network).getQueue().clear();subject=item;detailResolved=false;appShell("Watch");
        JSONObject cached=api.cachedDetail(item.optString("subjectId"));
        if(autoPlay&&item.optInt("subjectType")==1){subject=cached!=null?cached:item;playSelection(subject,0,0,false);playbackNeedsDetail=cached==null;return;}
        if(cached!=null){resolvedDetail(cached,autoPlay);return;}
        JSONObject display=api.cachedDisplayDetail(item.optString("subjectId"));
        if(display!=null){subject=display;detailResolved=true;readSeasons();restoreSavedEpisodeOnce(false);renderWatchLoading();status.setText("");}else{renderWatchLoading();status.setText("");}
        ((ThreadPoolExecutor)detailWork).getQueue().clear();
        workOn(detailWork,()->api.detail(item),detail->resolvedDetail(detail,autoPlay),error->{if(display==null)problem(error);});
    }

    private void resolvedDetail(JSONObject detail,boolean autoPlay){
        if(contentBlocked(detail)){toast("18+ content is disabled in Settings.");browse(route);return;}
        // Refresh metadata without moving someone already reading the same title.
        ScrollView previous=detailResolved&&subject!=null&&subject.optString("subjectId").equals(detail.optString("subjectId"))&&content.getChildCount()==1&&content.getChildAt(0) instanceof ScrollView?(ScrollView)content.getChildAt(0):null;
        final int previousY=previous==null?0:previous.getScrollY();
        subject=detail;detailResolved=true;readSeasons();restoreSavedEpisodeOnce(true);if(!autoPlay)renderWatchLoading();status.setText("");
        if(autoPlay){playSelection(subject,season,episode,false);return;}
        if(previous!=null&&content.getChildCount()==1&&content.getChildAt(0) instanceof ScrollView){
            final ScrollView refreshed=(ScrollView)content.getChildAt(0);final LinearLayout owner=content;final int request=generation;final String identity=detail.optString("subjectId");
            refreshed.getViewTreeObserver().addOnPreDrawListener(new android.view.ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){
                if(refreshed.getViewTreeObserver().isAlive())refreshed.getViewTreeObserver().removeOnPreDrawListener(this);
                if(!isFinishing()&&!isDestroyed()&&request==generation&&content==owner&&owner.getChildCount()==1&&owner.getChildAt(0)==refreshed&&subject!=null&&identity.equals(subject.optString("subjectId"))&&player==null)refreshed.scrollTo(0,previousY);
                return true;
            }});
        }
        if(api.getClass()!=Api.class)return; // Test/provider adapters own their own preparation policy.
        final JSONObject selected=subject;final int se=season,ep=episode;
        work(()->{api.prefetchPlayback(selected,se,ep,lowMemoryDevice?720:1080);return true;},ignored->{},ignored->{});
    }
    private void restoreSavedEpisodeOnce(boolean fresh){if(resumeSelectionPending){resumeSeriesSelection();if(fresh)resumeSelectionPending=false;}}
    private boolean resumeSeriesSelection(){
        if(subject.optInt("subjectType")!=2)return false;
        JSONObject history=library.data.optJSONObject("history");long latest=-1;int selectedSeason=season,selectedEpisode=episode;
        Iterator<String> keys=history.keys();while(keys.hasNext()){
            JSONObject item=history.optJSONObject(keys.next());if(item==null||item.optBoolean("completed")||item.optLong("position")<1000)continue;
            JSONObject title=item.optJSONObject("subject");int se=item.optInt("season"),ep=item.optInt("episode");
            if(title!=null&&title.optString("subjectId").equals(subject.optString("subjectId"))&&seasons.containsKey(se)&&contains(seasons.get(se),ep)&&item.optLong("updated")>latest){latest=item.optLong("updated");selectedSeason=se;selectedEpisode=ep;}
        }season=selectedSeason;episode=selectedEpisode;return latest>=0;
    }
    private void readSeasons(){seasons.clear();JSONArray rows=subject.optJSONArray("seasons");if(subject.optInt("subjectType")==2&&rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||row.optInt("se")<=0)continue;int[] numbers=Policies.episodes(row.optString("allEp"),row.optInt("maxEp"));if(numbers.length>0)seasons.put(row.optInt("se"),numbers);}
        if(seasons.isEmpty()){season=0;episode=0;}else if(!seasons.containsKey(season)){season=seasons.firstKey();episode=seasons.get(season)[0];}else if(!contains(seasons.get(season),episode))episode=seasons.get(season)[0];}
