    private void openDownloaded(Uri uri,String title){try{releasePlayer();generation++;subject=new JSONObject().put("subjectId","offline:"+uri.toString()).put("subjectType",1).put("title",title).put("description","Downloaded video on this device");currentAudio=subject;season=0;episode=0;seasons.clear();streams=new ArrayList<>();streams.add(new JSONObject().put("resourceLink",uri.toString()).put("resolution",0));streamIndex=0;captions=new ArrayList<>();startStream(library.position(subject,0,0),true,null);}catch(Exception error){problem(error);}}
    private boolean offline(){return subject!=null&&subject.optString("subjectId").startsWith("offline:");}
    private void requestDownload(){if(offline()||subject==null)return;requestDownload(subject,season,episode,720,false);}
    private void requestDownload(JSONObject chosen,int se,int ep,int preferred,boolean fresh){
        if(downloadLookupGeneration==generation){toast("Still finding download choices. Please wait a moment.");return;}downloadLookupGeneration=generation;if(status!=null)status.setText("Finding download qualities...");
        work(()->fresh?api.freshPlayback(chosen,se,ep,preferred):api.playback(chosen,se,ep),sources->{downloadLookupGeneration=-1;List<JSONObject> eligible=new ArrayList<>();List<String> labels=new ArrayList<>();for(JSONObject source:sources)if(!PhoneDownloads.format(source).isEmpty()){eligible.add(source);labels.add(source.optInt("resolution")+"p");}if(status!=null)status.setText("");if(labels.isEmpty()){toast("No supported single-file download is available for this video. You can still stream it.");return;}choiceSheet("Download quality",labels,-1,which->PhoneDownloads.enqueue(this,chosen,eligible.get(which),se,ep,()->{if(route.equals("Downloads")&&subject==null)browse("Downloads");}));},error->{downloadLookupGeneration=-1;if(status!=null)status.setText("");toast("Download choices could not load. Check your connection and try again.");});
    }

    private void episodeMenu(boolean inPlayer){if(seasons.isEmpty())return;if(inPlayer){showEpisodeDrawer();return;}List<Integer> numbers=new ArrayList<>(seasons.keySet());List<String> names=new ArrayList<>();for(int number:numbers)names.add("Season "+number);choiceSheet("Seasons",names,numbers.indexOf(season),which->{resumeSelectionPending=false;season=numbers.get(which);episode=seasons.get(season)[0];renderDetail();});}
    private void playSelection(JSONObject selection,int requestedSeason,int requestedEpisode,boolean fresh){
        if(contentBlocked(selection)){toast("18+ content is disabled in Settings.");return;}
        resumeSelectionPending=false;releasePlayer();generation++;((ThreadPoolExecutor)network).getQueue().clear();currentAudio=selection;season=requestedSeason;episode=requestedEpisode;
        // Leave a real Back/Watch route available while the first source is fetched.
        appShell("Watch");renderWatchLoading();status.setText("");
        work(()->api.initialPlayback(selection,requestedSeason,requestedEpisode,lowMemoryDevice?720:1080),result->{
            streams=result;streamIndex=0;captions=new ArrayList<>();long resume=fresh?0:library.position(subject,season,episode);startStream(resume,true,null);loadCaptions();
            final ExoPlayer active=player;
            // Other qualities are optional enrichment, never a gate on initial playback.
            work(()->{try{return api.playback(selection,requestedSeason,requestedEpisode);}catch(Exception ignored){return Collections.<JSONObject>emptyList();}},available->mergeAvailableQualities(available,active));
        });
    }
    private void mergeAvailableQualities(List<JSONObject> available,ExoPlayer expected){
        if(player!=expected||player==null||available.isEmpty()||streams.isEmpty()||streamIndex<0||streamIndex>=streams.size())return;
        JSONObject active=streams.get(streamIndex);String id=active.optString("resourceId"),link=active.optString("resourceLink");List<JSONObject> merged=new ArrayList<>();int activeIndex=-1;
        for(JSONObject candidate:available){boolean same=!id.isEmpty()?id.equals(candidate.optString("resourceId")):link.equals(candidate.optString("resourceLink"));if(same){activeIndex=merged.size();merged.add(active);}else merged.add(candidate);}
        if(activeIndex<0){merged.add(0,active);activeIndex=0;}streams=merged;streamIndex=activeIndex;
    }
    private MediaItem mediaItem(JSONObject source,File subtitle,String language){MediaItem.Builder item=new MediaItem.Builder().setUri(source.optString("resourceLink"));if(subtitle!=null){String mime=subtitle.getName().endsWith(".vtt")?MimeTypes.TEXT_VTT:MimeTypes.APPLICATION_SUBRIP;item.setSubtitleConfigurations(Collections.singletonList(new MediaItem.SubtitleConfiguration.Builder(Uri.fromFile(subtitle)).setMimeType(mime).setLanguage(language).setSelectionFlags(C.SELECTION_FLAG_DEFAULT).build()));}return item.build();}
