    private void qualityDialog(){final List<JSONObject> choices=new ArrayList<>(streams);final ExoPlayer expected=player;List<String> names=new ArrayList<>();for(JSONObject source:choices)names.add(source.optInt("resolution")+"p");choiceSheet("Video quality",names,streamIndex,which->{if(player==null||player!=expected||which<0||which>=choices.size())return;JSONObject selected=choices.get(which);int found=-1;for(int n=0;n<streams.size();n++){JSONObject candidate=streams.get(n);String id=selected.optString("resourceId"),link=selected.optString("resourceLink");if(selected.optInt("resolution")==candidate.optInt("resolution")&&(!id.isEmpty()?id.equals(candidate.optString("resourceId")):!link.isEmpty()&&link.equals(candidate.optString("resourceLink")))){found=n;break;}}if(found<0){toast("That quality changed. Please open quality again.");return;}long position=player.getCurrentPosition();boolean playing=player.getPlayWhenReady();streamIndex=found;generation++;startStream(position,playing,null);loadCaptions();});}
    private void audioDialog(){final ExoPlayer expected=player;List<Tracks.Group> groups=player==null?Collections.emptyList():player.getCurrentTracks().getGroups();List<String> names=new ArrayList<>();List<Format> formats=new ArrayList<>();List<Runnable> actions=new ArrayList<>();int selected=-1;for(Tracks.Group group:groups)if(group.getType()==C.TRACK_TYPE_AUDIO)for(int i=0;i<group.length;i++){if(!group.isTrackSupported(i))continue;final int index=i;Format format=group.getTrackFormat(i);if(group.isTrackSelected(i))selected=formats.size();formats.add(format);actions.add(()->{if(player!=null){player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setOverrideForType(new TrackSelectionOverride(group.getMediaTrackGroup(),index)).build());if(format.language!=null)try{library.settings().put("audioLanguage",format.language);library.save();}catch(Exception error){problem(error);}}});}
        names.addAll(AudioLabels.tracks(formats,Locale.getDefault()));JSONArray dubs=subject.optJSONArray("dubs");if(dubs!=null)for(int i=0;i<dubs.length();i++){JSONObject dub=dubs.optJSONObject(i);if(dub==null||dub.optInt("type",-1)!=0||dub.optString("subjectId").isEmpty())continue;names.add(AudioLabels.editionName(dub.optString("lanName"),dub.optString("lanCode"),i+1,Locale.getDefault()));actions.add(()->{try{JSONObject selection=new JSONObject(subject.toString()).put("subjectId",dub.getString("subjectId"));playSelection(selection,season,episode,true);}catch(Exception e){problem(e);}});}
        if(names.isEmpty()){LinearLayout rows=column();TextView note=text("No extra audio tracks for this video.",14);note.setTextColor(secondary);note.setPadding(dp(12),dp(12),dp(12),dp(18));rows.addView(note);showSheet("Audio",rows);return;}choiceSheet("Audio",names,selected,which->{if(player==expected)actions.get(which).run();});}

    private void loadCaptions(){loadCaptions(true);}
    private void loadCaptions(boolean automatic){if(streams.isEmpty()||currentAudio==null)return;JSONObject source=streams.get(streamIndex),audio=currentAudio;final ExoPlayer expected=player;final int request=captionRequest,listing=++captionListRequest;work(()->api.captions(audio,source),result->{if(player!=expected||listing!=captionListRequest)return;captions=result;if(automatic&&request==captionRequest&&library.settings().optBoolean("subtitles",true)){String preferred=library.settings().optString("subtitleLanguage","en");for(JSONObject caption:captions)if(caption.optString("lan",caption.optString("lanCode",caption.optString("language"))).equalsIgnoreCase(preferred)){useCaption(caption);break;}}});}
    private void subtitleDialog(){final ExoPlayer expected=player;final List<JSONObject> choices=new ArrayList<>(captions);List<String> labels=new ArrayList<>();labels.add("Off");int selected=library.settings().optBoolean("subtitles",true)?-1:0;String preferred=library.settings().optString("subtitleLanguage","en");for(JSONObject caption:choices){String language=caption.optString("lan",caption.optString("lanCode",caption.optString("language")));if(language.equalsIgnoreCase(preferred)&&selected!=0)selected=labels.size();labels.add(caption.optString("lanName",caption.optString("language",caption.optString("lan","Subtitle"))));}labels.add("Reload available subtitles");int reload=labels.size()-1;choiceSheet("Subtitles",labels,selected,which->{if(player!=expected)return;if(which==reload){loadCaptions();return;}if(which==0){captionRequest++;try{library.settings().put("subtitles",false);library.save();if(player!=null)player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setTrackTypeDisabled(C.TRACK_TYPE_TEXT,true).build());}catch(Exception error){problem(error);}}else useCaption(choices.get(which-1));});}

    private File cachedSubtitle(){
        if(currentAudio==null||streams.isEmpty())return null;
        String language=library.settings().optString("subtitleLanguage","en");
        String identity=currentAudio.optString("subjectId")+":"+season+":"+episode+":"+streams.get(streamIndex).optString("resourceId")+":"+language;
        return subtitleCache.find(identity);
    }
    private void useCaption(JSONObject caption){final int request=++captionRequest;final ExoPlayer expected=player;if(expected==null||currentAudio==null||streams.isEmpty())return;String language=caption.optString("lan",caption.optString("lanCode",caption.optString("language","en")));String url=caption.optString("url",caption.optString("captionUrl",caption.optString("subtitleUrl")));if(!url.startsWith("https://"))return;String identity=currentAudio.optString("subjectId")+":"+season+":"+episode+":"+streams.get(streamIndex).optString("resourceId")+":"+language;
        work(()->{File cached=subtitleCache.find(identity);if(cached!=null)return cached;String path=Uri.parse(url).getPath();String extension=path!=null&&path.toLowerCase(Locale.ROOT).endsWith(".vtt")?".vtt":".srt";return subtitleCache.put(identity,extension,api.captionBytes(url,SubtitleCache.MAX_FILE_BYTES));},file->{if(player==null||player!=expected||request!=captionRequest)return;if(!file.isFile()){toast("Subtitle cache changed. Choose the subtitle again.");return;}library.settings().put("subtitles",true).put("subtitleLanguage",language);library.save();subtitleCache.protect(file);MediaItem item=player.getCurrentMediaItem();if(item!=null&&item.localConfiguration!=null)for(MediaItem.SubtitleConfiguration existing:item.localConfiguration.subtitleConfigurations)if(existing.uri.equals(Uri.fromFile(file))){player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setTrackTypeDisabled(C.TRACK_TYPE_TEXT,false).build());return;}long position=player.getCurrentPosition();boolean playing=player.getPlayWhenReady();player.setMediaItem(mediaItem(streams.get(streamIndex),file,language),position);player.prepare();player.setPlayWhenReady(playing);player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setTrackTypeDisabled(C.TRACK_TYPE_TEXT,false).build());},error->{if(player==expected&&request==captionRequest)toast("Subtitles could not load or be saved. Check connection and storage, or choose another subtitle.");});}

    private String playbackFailureMessage(PlaybackException error){
        switch(error.errorCode){
            case PlaybackException.ERROR_CODE_IO_NETWORK_CONNECTION_FAILED:case PlaybackException.ERROR_CODE_IO_NETWORK_CONNECTION_TIMEOUT:return "Connection interrupted. Check your connection and retry, or go back.";
            case PlaybackException.ERROR_CODE_IO_BAD_HTTP_STATUS:return "The video address is unavailable. Retry to refresh it, choose another quality, or go back.";
            case PlaybackException.ERROR_CODE_DECODING_FAILED:case PlaybackException.ERROR_CODE_DECODER_INIT_FAILED:case PlaybackException.ERROR_CODE_DECODING_FORMAT_UNSUPPORTED:return "This video format could not play. Choose another quality or go back.";
            default:return "Playback stopped. Retry, choose another quality, or go back.";
        }
    }
    private void retryPlaybackSource(){
        if(player==null||recoveringSource)return;
        long now=SystemClock.elapsedRealtime();if(lastRecoveryAt>0&&now-lastRecoveryAt<2000)return;
        final ExoPlayer expected=player;
        if(offline()){boolean requested=expected.getPlayWhenReady();expected.prepare();expected.setPlayWhenReady(requested);return;}
        if(currentAudio==null||streams.isEmpty()||streamIndex<0||streamIndex>=streams.size())return;
        final JSONObject audio=currentAudio;final int se=season,ep=episode,quality=streams.get(streamIndex).optInt("resolution",1080),request=++recoveryRequest;
        recoveringSource=true;lastRecoveryAt=now;showControls(true);toast("Refreshing video source\u2026");
        work(()->api.freshPlayback(audio,se,ep,quality),sources->{
            if(player!=expected||request!=recoveryRequest)return;recoveringSource=false;
            if(sources.isEmpty()){toast("No playable source is available. Choose another quality or go back.");showControls(true);return;}
            int chosen=0;for(int i=0;i<sources.size();i++)if(sources.get(i).optInt("resolution")==quality){chosen=i;break;}
            JSONObject source=sources.get(chosen);MediaItem previous=expected.getCurrentMediaItem();if(previous==null)return;
            // Retain the current player, audio overrides, caption file/off state, volume and zoom.
            // Read position/intent now so a Pause or seek made during lookup is respected too.
            long position=Math.max(0,expected.getCurrentPosition());boolean play=expected.getPlayWhenReady();
            captionListRequest++;captions=new ArrayList<>();streams=new ArrayList<>(sources);streamIndex=chosen;
            expected.setMediaItem(previous.buildUpon().setUri(source.optString("resourceLink")).build(),position);expected.prepare();expected.setPlayWhenReady(play);loadCaptions(false);
            if(source.optInt("resolution")!=quality)toast("Previous quality is unavailable. Using "+source.optInt("resolution")+"p.");
        },error->{if(player!=expected||request!=recoveryRequest)return;recoveringSource=false;showControls(true);toast("Could not refresh the video. Check your connection, retry, or go back.");});
    }
    private void showEpisodeDrawer(){if(player==null||seasons.isEmpty()||drawerOpen)return;showControls(false);showEpisodeSheet(season);}
    /** Episodes uses the same native sheet and rows as the other phone player menus. */
    private void showEpisodeSheet(int displayedSeason){
        if(player==null||!seasons.containsKey(displayedSeason))return;
        if(episodeDialog!=null){openSheets.remove(episodeDialog);episodeDialog.setOnDismissListener(null);episodeDialog.dismiss();}
        drawerOpen=true;ui.removeCallbacks(hideControls);
        LinearLayout rows=column();
        HorizontalScrollView seasonScroll=new HorizontalScrollView(this);seasonScroll.setHorizontalScrollBarEnabled(false);
        LinearLayout seasonChoices=row();seasonChoices.setPadding(0,0,0,dp(8));
        for(int number:seasons.keySet()){
            Button choice=button("Season "+number,"Show season "+number+(number==displayedSeason?", selected":""),()->{if(number!=displayedSeason)showEpisodeSheet(number);});
            choice.setTextSize(14);choice.setSingleLine(true);choice.setTextColor(number==displayedSeason?accent:secondary);choice.setBackground(rounded(number==displayedSeason?selectionColor:Color.TRANSPARENT));
            LinearLayout.LayoutParams chip=new LinearLayout.LayoutParams(-2,dp(48));chip.rightMargin=dp(4);seasonChoices.addView(choice,chip);if(number==displayedSeason)choice.post(()->seasonScroll.smoothScrollTo(Math.max(0,choice.getLeft()-dp(12)),0));
        }
        seasonScroll.addView(seasonChoices);rows.addView(seasonScroll,new LinearLayout.LayoutParams(-1,-2));
        View currentRow=null;int[] numbers=seasons.get(displayedSeason);
        if(numbers!=null)for(int number:numbers){
            final boolean current=displayedSeason==season&&number==episode;
            LinearLayout item=sheetRow("Episode "+number+(current?player.getPlayWhenReady()?"  \u00b7  Playing":"  \u00b7  Paused":""),current);
            item.setContentDescription("Play season "+displayedSeason+" episode "+number+(current?", current":""));
            item.setOnClickListener(v->{hideEpisodeDrawer();if(!current&&player!=null)playSelection(currentAudio,displayedSeason,number,true);});
            rows.addView(item,new LinearLayout.LayoutParams(-1,-2));if(current)currentRow=item;
        }
        Dialog dialog=showSheet("Seasons & episodes",rows);episodeDialog=dialog;
        episodeDrawer=(ViewGroup)rows.getParent().getParent();episodeDrawer.setContentDescription("Seasons and episodes panel");
        dialog.setOnDismissListener(d->{finishSheet(dialog);if(episodeDialog==dialog){drawerOpen=false;episodeDialog=null;episodeDrawer=null;if(player!=null)showControls(false);}});
        final View selected=currentRow;if(selected!=null)selected.post(()->{if(episodeDialog==dialog){android.graphics.Rect area=new android.graphics.Rect();selected.getDrawingRect(area);selected.requestRectangleOnScreen(area,true);}});
    }
    private void hideEpisodeDrawer(){drawerOpen=false;if(episodeDialog!=null){Dialog dialog=episodeDialog;episodeDialog=null;dialog.dismiss();}episodeDrawer=null;if(player!=null)showControls(false);}

